using System.Windows;

// Tells WPF where to find default styles for the custom controls this assembly
// declares (currently Components/AudioIcon). "None" for theme-specific dictionaries -
// there are no Luna/Aero variants - and "SourceAssembly" for the generic one, which
// resolves to Themes/Generic.xaml here.
//
// Only this attribute lives in this file. Everything else AssemblyInfo normally holds
// is generated by the SDK from the .csproj, so declaring more here would produce
// duplicate-attribute errors.
[assembly: ThemeInfo(ResourceDictionaryLocation.None, ResourceDictionaryLocation.SourceAssembly)]
